    --stage-art-secondary: oklch(0.80968 0.117071 158.817);
    --stage-art-tertiary: oklch(0.784102 0.108047 88.516);
    --stage-art-line: oklch(0.981098 0.027812 158.718);
    --stage-night-top: oklch(0.45805 0.079616 160.092);
    --stage-night-mid: oklch(0.368483 0.065631 162.719);
    --stage-night-bottom: oklch(0.264797 0.044397 168.088);
    --stage-night-highlight: oklch(0.912563 0.055173 158.974);
    --stage-night-secondary: oklch(0.665652 0.109731 156.599);
    --stage-night-tertiary: oklch(0.698651 0.103024 89.828);
    --stage-night-line: oklch(0.945336 0.041923 157.222);

    @variant dark {
      --stage-art-top: oklch(0.58719 0.09869 157.426);
      --stage-art-mid: oklch(0.454979 0.079031 159.756);
      --stage-art-bottom: oklch(0.297856 0.050355 161.167);
      --stage-art-highlight: oklch(0.952407 0.053872 158.44);
      --stage-art-secondary: oklch(0.732591 0.120606 155.853);
      --stage-art-tertiary: oklch(0.716282 0.116547 80.563);
      --stage-art-line: oklch(0.961577 0.035285 157.03);
      --stage-night-top: oklch(0.398632 0.065534 158.601);
      --stage-night-mid: oklch(0.290561 0.049694 160.456);
      --stage-night-bottom: oklch(0.210147 0.03173 169.818);
      --stage-night-highlight: oklch(0.866303 0.057526 156.796);
      --stage-night-secondary: oklch(0.586553 0.093722 157.365);
      --stage-night-tertiary: oklch(0.6364 0.101769 82.985);
      --stage-night-line: oklch(0.913292 0.035718 156.976);
    }
  }

  html[data-theme-id="ocean"] {
    --stage-art-top: oklch(0.792993 0.088072 220.421);
    --stage-art-mid: oklch(0.590296 0.116841 243.184);
    --stage-art-bottom: oklch(0.409123 0.093718 247.98);
    --stage-art-highlight: oklch(0.971217 0.023008 213.615);
    --stage-art-secondary: oklch(0.788391 0.090856 215.684);
    --stage-art-tertiary: oklch(0.76441 0.099607 187.893);
    --stage-art-line: oklch(0.976025 0.019647 212.543);

    @variant dark {
      --stage-art-top: oklch(0.59663 0.089167 233.427);
      --stage-art-mid: oklch(0.461094 0.084904 243.478);
      --stage-art-bottom: oklch(0.294818 0.05947 250.526);
      --stage-art-highlight: oklch(0.952907 0.032224 221.27);
      --stage-art-secondary: oklch(0.732079 0.09296 224.414);
      --stage-art-tertiary: oklch(0.720885 0.095495 190.903);
      --stage-art-line: oklch(0.961039 0.027355 219.756);
    }
  }

  html[data-theme-id="ember"] {
    --stage-art-top: oklch(0.782439 0.118806 52.569);
